import test from 'node:test';
import assert from 'node:assert/strict';
import vm from 'node:vm';
import { readFileSync } from 'node:fs';
import { webcrypto } from 'node:crypto';
const source=readFileSync(new URL('../public/app.js',import.meta.url),'utf8');
function harness(storage=new Map<string,string>()){ const elements=new Map<string,any>(); const requests:any[]=[]; const events=new Map<string,Function[]>();
 const element=(id:string)=>{if(!elements.has(id))elements.set(id,{id,innerHTML:'',textContent:'',hidden:true,style:{},value:'',addEventListener(){},focus(){},querySelectorAll(){return []}});return elements.get(id)};
 const snapshot={mode:'runtime',runtime:{status:'configuration_required',message:'Set Morphz URL'},messages:[],jobs:[],approvals:[],csrfToken:'test-csrf'};
 const context=vm.createContext({console,URL,URLSearchParams,sessionStorage:{getItem:(k:string)=>storage.get(k)||null,setItem:(k:string,v:string)=>storage.set(k,v),removeItem:(k:string)=>storage.delete(k)},location:{search:'',hash:''},history:{pushState(){}},document:{getElementById:element,activeElement:null,hidden:true,querySelectorAll(){return []},addEventListener(name:string,fn:Function){events.set(name,[...(events.get(name)||[]),fn])}},window:{addEventListener(){},confirm(){return true}},setTimeout:()=>0,clearTimeout(){},clearInterval(){},setInterval(){},crypto:webcrypto,fetch:async(path:string,options:any)=>{requests.push({path,options});return {ok:true,json:async()=>snapshot}}});
 vm.runInContext(source,context);return {context,element,requests,events,run:(code:string)=>vm.runInContext(code,context)};
}
test('frontend renders all six views without fabricated live state',async()=>{const h=harness();await h.run('loadState(true)');for(const v of ['chat','tasks','files','memory','computer','settings']){h.run(`navigate('${v}')`);assert.ok(h.element('content').innerHTML.length>100)}h.run("navigate('computer')");assert.match(h.element('content').innerHTML,/未连接 · 输入已锁定/);assert.doesNotMatch(h.element('content').innerHTML,/<iframe|<video|stays.example/);});
test('runtime messages are escaped as untrusted text',()=>{const h=harness();h.run(`state.messages=[{role:'assistant',text:'<img src=x onerror=alert(1)>'}];navigate('chat')`);assert.match(h.element('content').innerHTML,/&lt;img/);assert.doesNotMatch(h.element('content').innerHTML,/<img src=x/);});
test('mutation requests carry csrf and expected revision',async()=>{const h=harness();h.run("state.csrfToken='test-csrf'");await h.run(`request('/api/jobs/task/control','POST',{action:'pause',expectedRevision:4,idempotencyKey:'stable'})`);const r=h.requests.find(r=>r.path==='/api/jobs/task/control');assert.equal(r.options.headers['x-opendots-csrf'],'test-csrf');assert.equal(JSON.parse(r.options.body).expectedRevision,4);});
test('BYOK uses password field and known safe returned fields only',()=>{const h=harness();h.run(`view='settings';settingsData={catalog:{current:'m',options:[{id:'m',label:'Model'}]},accounts:[],binding:{accountIds:[]},apiKey:'DO-NOT-RENDER'};render()`);const markup=h.element('model-settings').innerHTML;assert.match(markup,/type="password"/);assert.doesNotMatch(markup,/DO-NOT-RENDER/);assert.doesNotMatch(source,/localStorage|console\.log/);});
test('styles obey restrictive CSP and contain responsive layouts',()=>{const html=readFileSync(new URL('../public/index.html',import.meta.url),'utf8');const css=readFileSync(new URL('../public/styles.css',import.meta.url),'utf8');assert.doesNotMatch(html,/style="|<style>|<script>/);assert.doesNotMatch(source,/style="/);assert.match(css,/@media\(max-width:760px\)/);});

test('approval opened before changed polling submits only displayed revision',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`state.approvals=[{id:'a',revision:3,status:'pending_human',action:'read',available_scopes:['once']}];openApproval('a');state.approvals=[{id:'a',revision:4,status:'pending_human',action:'delete',available_scopes:['once']}]`);await h.run(`decideApproval('allow_once')`);const r=h.requests.find(r=>r.path==='/api/approvals/a/decision');assert.equal(JSON.parse(r.options.body).expectedRevision,3);});
test('BYOK retry ID survives reload without key or key hash storage',()=>{const storage=new Map<string,string>();const h=harness(storage);const config={label:'A',protocol:'openai-chat',baseUrl:'https://example.com',model:'m',apiKey:'NEVER-SAVE-SECRET'};const first=h.run(`prepareModelAttempt(${JSON.stringify(config)})`);const reloaded=harness(storage);assert.equal(reloaded.run(`prepareModelAttempt(${JSON.stringify(config)})`),first);assert.doesNotMatch([...storage.values()].join(''),/NEVER-SAVE-SECRET|apiKey/);assert.throws(()=>reloaded.run(`prepareModelAttempt({...${JSON.stringify(config)},model:'other'})`));reloaded.run('clearModelAttempt()');assert.notEqual(reloaded.run(`prepareModelAttempt(${JSON.stringify(config)})`),first);});
test('hash navigation never adds server query strings',()=>{const h=harness();h.run(`history.pushState=(a,b,url)=>{window.lastUrl=url};navigate('settings')`);assert.equal(h.run('window.lastUrl'),'#settings');});
test('real approval states and unavailable once scope render safely',()=>{const h=harness();h.run(`state.approvals=[{id:'a',revision:1,status:'pending_human',available_scopes:[]},{id:'b',revision:2,status:'pending_auto',available_scopes:['once']}];openApproval('a')`);assert.equal(h.run('pendingApprovals().length'),2);assert.match(h.element('modal').innerHTML,/data-decision="allow_once" disabled/);});
test('committed output removes matching draft rather than duplicating it',()=>{const h=harness();h.run(`state.messages=[{role:'assistant',root_turn_id:'r',text:'final'}];state.drafts=[{root_turn_id:'r',text:'partial',draft:true},{root_turn_id:'s',text:'another',draft:true}]`);assert.equal(h.run('visibleMessages().length'),2);assert.equal(h.run('visibleMessages().some(m=>m.text==="partial")'),false);});
test('reload during submitting reuses durable original chat key',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`state.mode='runtime';state.runtime={status:'ready'};state.commands=[{id:'c',kind:'chat',status:'submitting',key:'original-key',payload:{text:'hello'}}];document.getElementById('message-input').value='hello';document.getElementById('background-task').checked=false`);await h.run(`sendMessage({preventDefault(){}})`);const submitted=h.requests.find(r=>r.path==='/api/chat');assert.equal(JSON.parse(submitted.options.body).idempotencyKey,'original-key');});
test('unknown objective cannot send retained revision control',async()=>{const h=harness();h.run(`state.jobs=[{id:'o',revision:4,status:'unknown'}]`);await h.run(`controlJob('o','pause')`);assert.equal(h.requests.some(r=>r.path==='/api/jobs/o/control'),false);});
test('BYOK rejects credentials in base URL before persisting fingerprint',()=>{const storage=new Map<string,string>();const h=harness(storage);assert.throws(()=>h.run(`prepareModelAttempt({label:'A',protocol:'openai-chat',baseUrl:'https://example.com?api_key=SECRET',model:'m'})`));assert.equal(storage.size,0);});
test('leaving during takeover releases returned human lease without attaching frame',async()=>{const h=harness();h.run(`view='computer';computerData.state={epoch:2};window.computerCalls=[];request=async(path,method,body)=>{window.computerCalls.push({path,body});if(path.endsWith('/takeover')){computerGeneration++;return {state:{epoch:3},connection:{viewOnly:false}}}return {}}`);await h.run(`connectDesktop('takeover')`);const calls=h.run('window.computerCalls');assert.equal(calls[1].path,'/api/computer/pause');assert.equal(calls[1].body.expectedEpoch,3);});
test('notification inbox escapes source text and clearly stays in app',()=>{const h=harness();h.run(`notificationView={mode:'all',unread:1,items:[{id:'n',title:'<img onerror=x>',reason:'<script>bad</script>',target:'approvals',sourceStatus:'pending_human',createdAt:1}]};renderNotifications(true)`);const markup=h.element('modal').innerHTML;assert.match(markup,/仅保存在这个应用内/);assert.match(markup,/&lt;script&gt;/);assert.doesNotMatch(markup,/<script>|<img onerror/);assert.doesNotMatch(source,/Notification\.requestPermission/);});
test('memory UI only exposes supported official API operations',()=>{const h=harness();h.run(`navigate('memory')`);assert.match(h.element('content').innerHTML,/不设手动编辑入口/);assert.doesNotMatch(source,/api\/memory\/(capabilities|change)|memoryEditAllowed|openMemoryEditor/);assert.doesNotMatch(source,/api\/memory\/lifecycle|data-memory-action/);});
test('voice close aborts upload, releases capture and clears ephemeral content',async()=>{const h=harness();h.run(`window.cleanupCounts={abort:0,cancel:0,pause:0,revoke:0};URL={revokeObjectURL(){window.cleanupCounts.revoke++}};voiceSession={text:'private transcript',blob:{},capture:{async cancel(){window.cleanupCounts.cancel++}},controller:{abort(){window.cleanupCounts.abort++}},audio:{pause(){window.cleanupCounts.pause++},removeAttribute(){},load(){}},audioUrl:'blob:local'};window.oldVoice=voiceSession`);await h.run('cleanupVoice()');assert.equal(h.run('voiceSession'),null);assert.equal(h.run('window.oldVoice.blob'),null);assert.equal(h.run('window.oldVoice.text'),'');for(const key of ['abort','cancel','pause','revoke'])assert.equal(h.run(`window.cleanupCounts.${key}`),1);});
test('transcript retry preserves exact ordinary chat payload and key',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`voiceSession={kind:'record',status:'review',cap:{available:true,provider:{label:'Provider',destination:'example.com'},operations:{}},text:'hello'};renderVoice(true);document.getElementById('voice-transcript').value='hello';window.voiceRequests=[];request=async(path,method,body)=>{if(path==='/api/chat'){window.voiceRequests.push(body);throw new Error('uncertain')}return state}`);await h.run('sendVoiceTranscript()');h.run(`document.getElementById('voice-transcript').value='changed after uncertain send'`);await h.run('sendVoiceTranscript()');const values=h.run('window.voiceRequests');assert.equal(values.length,2);assert.equal(values[0].idempotencyKey,values[1].idempotencyKey);assert.equal(values[1].text,'hello');});
test('read aloud affordance excludes streaming draft and unconfigured voice',()=>{const h=harness();h.run(`state.messages=[{id:'final',role:'assistant',text:'committed'}];state.drafts=[{id:'draft',role:'assistant',text:'unfinished',draft:true}];voiceCapability={operations:{readAloud:true}};navigate('chat')`);assert.match(h.element('content').innerHTML,/data-read-aloud="final"/);assert.doesNotMatch(h.element('content').innerHTML,/data-read-aloud="draft"/);h.run(`voiceCapability={operations:{readAloud:false}};render()`);assert.doesNotMatch(h.element('content').innerHTML,/data-read-aloud=/);});
for(const kind of ['memory','notifications'])test(`late ${kind} response cannot replace newer recording modal`,async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`window.resolveOld=null;request=async(path)=>{if(path==='${kind==='memory'?'/api/memory/read':'/api/notifications'}')return new Promise(resolve=>window.resolveOld=resolve);if(path==='/api/voice')return {available:true,provider:{label:'豆包',destination:'openspeech.bytedance.com'},operations:{transcribe:true},capture:{maximumSeconds:30}};return state};window.oldModalRequest=${kind==='memory'?"readMemory('f')":"openNotifications()"}`);await h.run('openVoice()');h.run(`voiceSession.status='recording';voiceSession.capture={async cancel(){window.cancelled=true}};renderVoice();window.resolveOld(${kind==='memory'?"{id:'f',body:'old response',sources:[],mindVersion:1}":"{items:[],mode:'all'}"})`);await h.run('window.oldModalRequest');assert.equal(h.run('voiceSession.status'),'recording');assert.match(h.element('modal').innerHTML,/正在本地录音/);assert.equal(h.run('window.cancelled'),undefined);});
test('winning nonvoice modal always releases active microphone session',async()=>{const h=harness();h.run(`window.stopped=0;voiceSession={text:'x',capture:{async cancel(){window.stopped++}}};openModal('<h2>Approval</h2>')`);await new Promise(r=>setImmediate(r));assert.equal(h.run('voiceSession'),null);assert.equal(h.run('window.stopped'),1);assert.match(h.element('modal').innerHTML,/Approval/);});
test('attachment persistence contains only retry identities, never bytes or file metadata',()=>{const storage=new Map<string,string>();const h=harness(storage);h.run(`state.binding={sessionId:'session'};attachmentDraft={draftKey:'draft-key',commandKey:'message-key'};attachmentItems=[{id:'upload-id',uploadKey:'upload-key',name:'private.txt',sha256:'private-hash',file:'PRIVATE BYTES',text:'secret'}];saveAttachmentIdentities()`);const saved=[...storage.values()].join('');assert.match(saved,/draft-key|upload-key|message-key/);assert.doesNotMatch(saved,/private|PRIVATE|secret|sha256|name/);});
test('lost create response reload matches uploadKey without creating another stage',async()=>{const storage=new Map<string,string>();storage.set('opendots:attachment-draft:session',JSON.stringify({draftKey:'draft-key',commandKey:null,uploads:[{uploadKey:'stable-key',id:null}]}));const h=harness(storage);await new Promise(r=>setImmediate(r));h.run(`state.binding={sessionId:'session'};window.uploadCalls=[];request=async(path,method)=>{window.uploadCalls.push({path,method});return {uploads:[{id:'same-upload',uploadKey:'stable-key',draftKey:'draft-key',status:'uploading',offset:3,name:'a.txt',sizeBytes:10}],limits:{}}}`);await h.run('loadAttachments()');assert.equal(h.run('attachmentItems[0].id'),'same-upload');assert.equal(h.run('attachmentItems[0].file'),null);assert.equal(h.run('window.uploadCalls.some(c=>c.method===\"POST\")'),false);});
test('restoring unresolved attachment command retains ordered file identities',()=>{const h=harness();h.run(`state.binding={sessionId:'session'};restoreAttachmentCommand({key:'original-key',payload:{text:'review files',draftKey:'draft-key',uploadIds:['second','first']}})`);assert.equal(h.run('pendingSubmission.key'),'original-key');assert.equal(h.run('JSON.stringify(activeAttachments().map(i=>i.id))'),'["second","first"]');assert.equal(h.run('attachmentDraft.commandKey'),'original-key');});
test('definite pre-admission attachment rejection unlocks only after unsealed no-command proof',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`state.binding={sessionId:'session'};attachmentDraft={draftKey:'draft-key',commandKey:'send-key'};attachmentItems=[{id:'upload-id',uploadKey:'upload-key',status:'ready'}];attachmentRejection={key:'send-key',status:409};request=async(path)=>path==='/api/state'?{binding:{sessionId:'session'},runtime:{status:'ready'},commands:[]}:{uploads:[{id:'upload-id',draftKey:'draft-key',status:'missing',sealed:false}]}`);await h.run('unlockRejectedAttachmentDraft()');assert.equal(h.run('attachmentDraft.commandKey'),null);assert.equal(h.run('attachmentItems[0].status'),'missing');});
test('unknown or server-saved attachment submission cannot be unlocked',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`state.binding={sessionId:'session'};attachmentDraft={draftKey:'draft-key',commandKey:'send-key'};attachmentItems=[{id:'upload-id',uploadKey:'upload-key',status:'ready'}];attachmentRejection=null;window.unlockCalls=0;request=async()=>{window.unlockCalls++;return {binding:{sessionId:'session'},runtime:{status:'ready'},commands:[{key:'send-key',status:'unknown'}]}}`);await h.run('unlockRejectedAttachmentDraft()');assert.equal(h.run('window.unlockCalls'),0);h.run(`attachmentRejection={key:'send-key',status:409}`);await h.run('unlockRejectedAttachmentDraft()');assert.equal(h.run('attachmentDraft.commandKey'),'send-key');});
test('cancelling upload cannot be sent or resumed',async()=>{const h=harness();h.run(`attachmentDraft={draftKey:'draft-key',commandKey:null};attachmentItems=[{id:'upload-id',uploadKey:'upload-key',status:'cancelling',file:{}}]`);assert.equal(h.run('attachmentsReady()'),false);const before=h.requests.length;await h.run(`uploadAttachment('upload-key')`);assert.equal(h.requests.length,before);});
test('attachment message retry sends exact frozen draft and ordered uploads',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`state.mode='runtime';state.runtime={status:'ready'};state.binding={sessionId:'session'};state.commands=[{kind:'chat',key:'same-key',status:'unknown',payload:{text:'read these',draftKey:'draft-key',uploadIds:['b','a']}}];restoreAttachmentCommand(state.commands[0]);document.getElementById('message-input').value='read these';document.getElementById('background-task').checked=false;window.attachmentPosts=[];request=async(path,method,body)=>{if(path==='/api/chat'){window.attachmentPosts.push(JSON.parse(JSON.stringify(body)));throw new Error('lost response')}if(path==='/api/uploads')return {uploads:[{id:'b',draftKey:'draft-key',uploadKey:'b',status:'ready',sealed:true},{id:'a',draftKey:'draft-key',uploadKey:'a',status:'ready',sealed:true}],limits:{}};return state}`);await h.run('sendMessage({preventDefault(){}})');await h.run('sendMessage({preventDefault(){}})');const posts=h.run('window.attachmentPosts');assert.equal(posts.length,2);for(const p of posts){assert.equal(p.idempotencyKey,'same-key');assert.equal(p.draftKey,'draft-key');assert.equal(JSON.stringify(p.uploadIds),'["b","a"]');}assert.equal(h.run('attachmentDraft.commandKey'),'same-key');});
test('expired ready upload rejected before admission can unlock cancel and reselect locally',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.context.newFile={name:'new.txt',type:'text/plain',size:3,arrayBuffer:async()=>new TextEncoder().encode('new').buffer};h.run(`state.mode='runtime';state.runtime={status:'ready'};state.binding={sessionId:'session'};state.commands=[];attachmentDraft={draftKey:'draft-key',commandKey:null};attachmentItems=[{id:'upload-id',uploadKey:'upload-key',name:'old.txt',sizeBytes:3,status:'ready'}];document.getElementById('message-input').value='review';document.getElementById('background-task').checked=false;window.createPosts=0;request=async(path,method,body)=>{if(path==='/api/chat'){const error=new Error('expired');error.status=409;throw error}if(path.endsWith('/cancel'))return {id:'upload-id',status:'cancelled'};if(path==='/api/uploads'&&method==='POST'){window.createPosts++;return {}}if(path==='/api/uploads')return {uploads:[{id:'upload-id',uploadKey:'upload-key',draftKey:'draft-key',status:'missing',sealed:false,sizeBytes:3}],limits:{maximumBytes:10485760,maximumFiles:4,maximumDraftBytes:20971520,mediaTypes:['text/plain']}};return state}`);await h.run('sendMessage({preventDefault(){}})');assert.ok(h.run('attachmentDraft.commandKey'));await h.run('unlockRejectedAttachmentDraft()');assert.equal(h.run('attachmentDraft.commandKey'),null);await h.run("cancelAttachment('upload-key')");assert.equal(h.run('activeAttachments().length'),0);await h.run('chooseAttachments([newFile])');assert.equal(h.run('activeAttachments()[0].status'),'local');assert.equal(h.run('window.createPosts'),0);});
test('definitive attachment rejection survives reload but still requires fresh unlock proof',async()=>{const storage=new Map<string,string>();const h=harness(storage);await new Promise(r=>setImmediate(r));h.run(`state.mode='runtime';state.runtime={status:'ready'};state.binding={sessionId:'session'};state.commands=[];attachmentDraft={draftKey:'draft-key',commandKey:null};attachmentItems=[{id:'upload-id',uploadKey:'upload-key',status:'ready'}];document.getElementById('message-input').value='original';document.getElementById('background-task').checked=false;request=async(path)=>{if(path==='/api/chat'){const e=new Error('expired');e.status=409;throw e}if(path==='/api/uploads')return {uploads:[{id:'upload-id',uploadKey:'upload-key',draftKey:'draft-key',status:'missing',sealed:false}],limits:{}};return state}`);await h.run('sendMessage({preventDefault(){}})');const persisted=JSON.parse(storage.get('opendots:attachment-draft:session')!);assert.equal(persisted.rejection.status,409);const reloaded=harness(storage);await new Promise(r=>setImmediate(r));reloaded.run(`state.binding={sessionId:'session'};restoreAttachmentIdentities();window.proofs=0;request=async(path)=>{window.proofs++;return path==='/api/state'?{runtime:{status:'ready'},binding:{sessionId:'session'},commands:[]}:{uploads:[{id:'upload-id',draftKey:'draft-key',status:'missing',sealed:false}]}}`);await reloaded.run('unlockRejectedAttachmentDraft()');assert.equal(reloaded.run('window.proofs'),2);assert.equal(reloaded.run('attachmentDraft.commandKey'),null);});
test('unknown attachment send after a prior rejection clears persisted rejection proof',async()=>{const storage=new Map<string,string>();const h=harness(storage);await new Promise(r=>setImmediate(r));h.run(`state.mode='runtime';state.runtime={status:'ready'};state.binding={sessionId:'session'};state.commands=[];attachmentDraft={draftKey:'draft-key',commandKey:'same-key'};attachmentItems=[{id:'upload-id',uploadKey:'upload-key',status:'ready'}];attachmentRejection={key:'same-key',status:409};saveAttachmentIdentities();document.getElementById('message-input').value='original';document.getElementById('background-task').checked=false;request=async(path)=>{if(path==='/api/chat')throw new Error('lost response');if(path==='/api/uploads')return {uploads:[],limits:{}};return state}`);await h.run('sendMessage({preventDefault(){}})');assert.equal(JSON.parse(storage.get('opendots:attachment-draft:session')!).rejection,null);const reloaded=harness(storage);await new Promise(r=>setImmediate(r));reloaded.run(`state.binding={sessionId:'session'};restoreAttachmentIdentities();window.proofs=0;request=async()=>{window.proofs++;return {}}`);await reloaded.run('unlockRejectedAttachmentDraft()');assert.equal(reloaded.run('window.proofs'),0);assert.equal(reloaded.run('attachmentDraft.commandKey'),'same-key');});
test('task supplement freezes displayed generation and never answers unseen question',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`state.binding={sessionId:'session'};window.target={objectiveId:'o',generation:3,revision:9,status:'active',available:true,replyRequestId:'unseen-question',replyAvailable:false};window.taskPosts=[];request=async(path,method,body)=>{if(path.endsWith('/input-target'))return window.target;if(path.endsWith('/input')){window.taskPosts.push(JSON.parse(JSON.stringify(body)));throw new Error('unconfirmed')}return state}`);await h.run("openTaskInput('o')");h.run(`document.getElementById('task-input-text').value='Use the quiet option';window.target.generation=4;state.jobs=[{id:'o',generation:4}]`);await h.run('submitTaskInput()');h.run(`document.getElementById('task-input-text').value='changed text'`);await h.run('submitTaskInput()');const posts=h.run('window.taskPosts');assert.equal(posts.length,2);assert.equal(posts[0].expectedGeneration,3);assert.equal(posts[1].expectedGeneration,3);assert.equal(posts[0].idempotencyKey,posts[1].idempotencyKey);assert.equal(posts[1].text,'Use the quiet option');assert.equal('replyToRequestId' in posts[0],false);});
test('unknown task supplement restores durable original execution identity',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`state.commands=[{kind:'objective_input',status:'unknown',key:'saved-task-key',payload:{objectiveId:'o',text:'original',expectedGeneration:2}}];window.targetReads=0;request=async(path)=>{if(path.endsWith('/input-target'))window.targetReads++;return state}`);await h.run("openTaskInput('o')");assert.equal(h.run('taskInputSession.target.generation'),2);assert.equal(h.run('taskInputSession.key'),'saved-task-key');assert.equal(h.run('window.targetReads'),0);assert.match(h.element('modal').innerHTML,/readonly/);});
test('late task-input failure cannot replace newer voice recording',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`state.binding={sessionId:'session'};request=async(path)=>{if(path.endsWith('/input-target'))return {objectiveId:'o',generation:1,available:true};if(path.endsWith('/input'))return new Promise((resolve,reject)=>window.rejectTask=reject);if(path==='/api/voice')return {available:true,provider:{label:'豆包',destination:'openspeech.bytedance.com'},operations:{transcribe:true},capture:{maximumSeconds:30}};return state}`);await h.run("openTaskInput('o')");h.run(`document.getElementById('task-input-text').value='hello';window.taskSend=submitTaskInput()`);await h.run('openVoice()');h.run(`voiceSession.status='recording';renderVoice();window.rejectTask(new Error('unconfirmed'))`);await h.run('window.taskSend');assert.equal(h.run('voiceSession.status'),'recording');assert.match(h.element('modal').innerHTML,/正在本地录音/);});
test('task-input attempt identity survives reload before server command is visible',async()=>{const storage=new Map<string,string>();const first=harness(storage);await new Promise(r=>setImmediate(r));first.run(`state.binding={sessionId:'session'};state.commands=[];request=async(path)=>{if(path.endsWith('/input-target'))return {objectiveId:'o',generation:3,available:true};if(path.endsWith('/input'))throw new Error('lost response');return state}`);await first.run("openTaskInput('o')");first.run(`document.getElementById('task-input-text').value='private original text'`);await first.run('submitTaskInput()');const saved=JSON.parse(storage.get('opendots:task-input:session')!)[0];assert.equal(saved.generation,3);assert.doesNotMatch(JSON.stringify(saved),/private original text|text/);const second=harness(storage);await new Promise(r=>setImmediate(r));second.run(`state.binding={sessionId:'session'};state.commands=[];window.targetReads=0;window.replayed=null;request=async(path,method,body)=>{if(path.endsWith('/input-target')){window.targetReads++;return {objectiveId:'o',generation:99,available:true}}if(path.endsWith('/input')){window.replayed=body;return {status:'accepted'}}return state}`);await second.run("openTaskInput('o')");assert.equal(second.run('taskInputSession.needsOriginalText'),true);assert.equal(second.run('taskInputSession.target.generation'),3);assert.equal(second.run('window.targetReads'),0);second.run(`document.getElementById('task-input-text').value='private original text'`);await second.run('submitTaskInput()');assert.equal(second.run('window.replayed.idempotencyKey'),saved.key);assert.equal(second.run('window.replayed.expectedGeneration'),3);});
test('local-only supplement remains recoverable after task pauses or ends',async()=>{const storage=new Map<string,string>();storage.set('opendots:task-input:session',JSON.stringify([{objectiveId:'o',generation:3,key:'old-attempt'}]));const h=harness(storage);await new Promise(r=>setImmediate(r));h.run(`state.binding={sessionId:'session'};state.commands=[];window.newTargetReads=0;request=async(path)=>{if(path.endsWith('/input-target'))window.newTargetReads++;return state}`);for(const status of ['paused','completed']){const html=h.run(`jobCard({id:'o',prompt:'Original task',status:'${status}',generation:7,revision:9})`);assert.match(html,/查看原请求/);assert.doesNotMatch(html,/>补充说明<\/button>/);}await h.run("openTaskInput('o')");assert.equal(h.run('window.newTargetReads'),0);assert.equal(h.run('taskInputSession.key'),'old-attempt');assert.equal(h.run('taskInputSession.target.generation'),3);});

test('computer uncertainty remains visible and canceled acknowledgement sends nothing',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`view='computer';computerData={configured:true,state:{epoch:7,owner:'human',uncertainty:true},capabilities:{aiControl:true}};document.getElementById('content').innerHTML=computer();updateComputer();window.confirm=()=>false`);assert.equal(h.element('computer-uncertainty').hidden,false);assert.match(h.element('content').innerHTML,/归还给 AI 不会撤销已经发生的外部影响/);await h.run(`computerAction('return')`);assert.equal(h.requests.some(r=>r.path==='/api/computer/return'),false);assert.equal(h.run('computerData.state.uncertainty'),true);});
test('computer return confirms exact displayed epoch and preserves uncertainty after acknowledgement',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`view='computer';computerData={configured:true,state:{epoch:7,owner:'human',uncertainty:true},capabilities:{aiControl:true}};window.calls=[];window.confirm=()=>{computerData.state.epoch=8;return true};request=async(path,method,body)=>{window.calls.push({path,body});return computerData}`);await h.run(`computerAction('return')`);const call=h.run(`window.calls.find(c=>c.path==='/api/computer/return')`);assert.equal(call.body.expectedEpoch,7);assert.equal(call.body.acknowledgeUncertainty,true);assert.equal(h.run('computerData.state.uncertainty'),true);assert.equal(h.element('computer-uncertainty').hidden,false);});
test('computer return stays unavailable without trusted AI capability',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`computerData={configured:true,state:{epoch:7,uncertainty:true},capabilities:{aiControl:false}};window.confirm=()=>{throw new Error('must stay disabled')}`);await h.run(`computerAction('return')`);assert.equal(h.requests.some(r=>r.path==='/api/computer/return'),false);});

const computerApprovalFixture={id:'11111111-1111-4111-8111-111111111111',revision:3,status:'pending',epoch:7,observationId:'observation',expiresAt:Date.now()+60000,action:{type:'type',text:'<script>private</script>'},imagePath:'/api/computer/approvals/11111111-1111-4111-8111-111111111111/image',display:{width:100,height:80},actionable:true};
function openComputerFixture(h:ReturnType<typeof harness>,overrides={}){h.run(`window.imageHandlers={};document.getElementById('computer-approval-image').addEventListener=(kind,fn)=>{window.imageHandlers[kind]=fn};computerApprovalList=[${JSON.stringify({...computerApprovalFixture,...overrides})}];openComputerApproval('${computerApprovalFixture.id}')`);}
test('computer approval requires exact loaded image and retains displayed action revision',async()=>{const h=harness();await new Promise(r=>setImmediate(r));openComputerFixture(h);assert.match(h.element('modal').innerHTML,/&lt;script&gt;private/);assert.doesNotMatch(h.element('modal').innerHTML,/<script>/);await h.run(`decideComputerApproval('allow_once')`);assert.equal(h.requests.some(r=>r.path.endsWith('/decision')),false);h.run(`document.getElementById('computer-approval-image').naturalWidth=100;document.getElementById('computer-approval-image').naturalHeight=80;window.imageHandlers.load();computerApprovalList=[{id:'${computerApprovalFixture.id}',revision:99,action:{type:'key',key:'Enter'}}]`);assert.equal(h.element('computer-approval-allow').disabled,false);await h.run(`decideComputerApproval('allow_once')`);const r=h.requests.find(r=>r.path.endsWith('/decision'));assert.equal(JSON.parse(r.options.body).expectedRevision,3);assert.equal(JSON.parse(r.options.body).decision,'allow_once');assert.equal(h.element('modal').innerHTML,'');});
test('computer denial needs no screenshot; missing, failed, mismatched or expired images cannot approve',async()=>{for(const mode of ['missing','failed','mismatch','expired','no-dimensions']){const h=harness();await new Promise(r=>setImmediate(r));openComputerFixture(h,mode==='missing'?{imagePath:null}:{});if(mode==='no-dimensions')h.run(`activeComputerApproval.snapshot.display=null;document.getElementById('computer-approval-image').naturalWidth=100;document.getElementById('computer-approval-image').naturalHeight=80;window.imageHandlers.load()`);if(mode==='failed')h.run('window.imageHandlers.error()');if(mode==='mismatch')h.run(`document.getElementById('computer-approval-image').naturalWidth=1;document.getElementById('computer-approval-image').naturalHeight=1;window.imageHandlers.load()`);if(mode==='expired')h.run(`activeComputerApproval.imageLoaded=true;activeComputerApproval.snapshot.expiresAt=1;updateComputerApprovalButtons()`);await h.run(`decideComputerApproval('allow_once')`);assert.equal(h.requests.some(r=>r.path.endsWith('/decision')),false);if(mode==='missing'){await h.run(`decideComputerApproval('deny')`);assert.equal(JSON.parse(h.requests.find(r=>r.path.endsWith('/decision')).options.body).decision,'deny');}}});
test('closing computer approval discards private action and ignores late image load',()=>{const storage=new Map<string,string>();const h=harness(storage);openComputerFixture(h);h.run('closeModal();window.imageHandlers.load()');assert.equal(h.run('activeComputerApproval'),null);assert.equal(h.element('modal').innerHTML,'');assert.equal(storage.size,0);assert.equal(h.requests.some(r=>r.path.endsWith('/decision')),false);});
test('late computer approval inventory cannot hide active recording',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`request=()=>new Promise(resolve=>window.resolveApprovals=resolve);window.pendingList=openComputerApprovals();openModal('recording',{voice:true});voiceSession={status:'recording'};window.resolveApprovals({available:true,approvals:[]})`);await h.run('window.pendingList');assert.equal(h.element('modal').innerHTML,'recording');assert.equal(h.run('voiceSession.status'),'recording');});
test('computer pending approvals attract attention on both chat and task views',()=>{const h=harness();h.run('state.computerPendingApprovals=2');for(const v of ['chat','tasks']){h.run(`navigate('${v}')`);assert.match(h.element('content').innerHTML,/2 项电脑操作等待你确认/);}});

test('approved rich first-direction layout preserves panels and functional controls with coherent icons',()=>{const h=harness();h.run(`state.jobs=[{id:'job',prompt:'真实任务',status:'active',revision:2,generation:1}];state.approvals=[{id:'approval',status:'pending_human',revision:1}];navigate('chat')`);const html=h.element('content').innerHTML;assert.match(html,/class="workspace"/);assert.match(html,/class="conversation"/);assert.match(html,/class="rail"/);assert.match(html,/共享电脑/);assert.match(html,/data-job-input="job"/);assert.match(html,/data-approval="approval"/);assert.match(html,/id="attachment-input"/);assert.match(html,/id="background-task"/);assert.match(html,/class="composer-tools"/);assert.match(html,/每一步，都有人和你一起。/);assert.doesNotMatch(html,/YOUR CONTINUOUS COMPANION|设计预览|示例任务/);assert.match(h.element('nav').innerHTML,/<svg class="ui-icon"/);assert.match(h.element('nav').innerHTML,/aria-current="page"/);});
test('refined stylesheet keeps responsive rich layout and reduced motion support',()=>{const css=readFileSync(new URL('../public/styles.css',import.meta.url),'utf8');assert.match(css,/--deep:#244c40/);assert.match(css,/\.workspace\{grid-template-columns:minmax\(400px,1fr\) minmax\(340px,29%\)/);assert.match(css,/@media\(max-width:1000px\) and \(min-width:761px\)/);assert.match(css,/@media\(prefers-reduced-motion:reduce\)/);});

