test('revocation submits only the exact displayed device identity despite list changes',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`view='settings';ownerSessions={enabled:true,devices:[{id:'original',deviceLabel:'Laptop',current:false,createdAt:1,lastSeenAt:2}]};document.getElementById('owner-session-confirm').addEventListener=(kind,fn)=>window.confirmRevoke=fn;openOwnerSessionAction('revoke','original');ownerSessions.devices=[{id:'replacement',deviceLabel:'Other',current:false}];window.calls=[];request=async(path,method,body)=>{window.calls.push({path,method,body});if(path==='/api/auth')return {enabled:false};return {}}`);await h.run('window.confirmRevoke()');assert.equal(h.run(`window.calls.find(c=>c.method==='POST').path`),'/api/auth/devices/original/revoke');});
