test('private 401 releases live media and state before redirect, late response cannot restore it',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`window.closed={rfb:0,audio:0,upload:0};location.replace=path=>window.redirect=path;state.messages=[{text:'private'}];draft='private';rfb={disconnect(){window.closed.rfb++}};voiceSession={text:'secret',capture:{async cancel(){window.closed.audio++}}};uploadController={abort(){window.closed.upload++}};attachmentItems=[{file:'privatebytes'}];window.resolveSlow=null;fetch=async(path)=>path==='/slow'?new Promise(resolve=>window.resolveSlow=resolve):({status:401,ok:false});window.pendingSlow=request('/slow').catch(()=>{});`);await assert.rejects(h.run(`request('/api/models')`));h.run(`window.resolveSlow({status:200,ok:true,json:async()=>({messages:[{text:'late private'}]})})`);await h.run('window.pendingSlow');await new Promise(r=>setImmediate(r));assert.equal(h.run('window.redirect'),'/login');assert.equal(h.run('state.messages.length'),0);assert.equal(h.run('draft'),'');assert.equal(h.run('attachmentItems.length'),0);assert.equal(h.run('voiceSession'),null);assert.equal(h.run('window.closed.rfb'),1);assert.equal(h.run('window.closed.audio'),1);assert.equal(h.run('window.closed.upload'),1);assert.doesNotMatch(h.element('content').innerHTML,/private/);});
test('logout-all explicitly includes current session and sends csrf protected mutation',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`ownerSessions={enabled:true,devices:[]};state.csrfToken='device-csrf';location.replace=path=>window.redirect=path;document.getElementById('owner-session-confirm').addEventListener=(kind,fn)=>window.confirmRevoke=fn;openOwnerSessionAction('all')`);assert.match(h.element('modal').innerHTML,/包括当前/);await h.run('window.confirmRevoke()');const r=h.requests.find(r=>r.path==='/api/auth/revoke-all');assert.equal(r.options.headers['x-opendots-csrf'],'device-csrf');assert.equal(h.run('window.redirect'),'/login');});

test('originally current device row stays pinned after another tab replaces the login cookie',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`view='settings';ownerSessions={enabled:true,devices:[{id:'old-session',deviceLabel:'Original current',current:true}]};document.getElementById('owner-session-confirm').addEventListener=(kind,fn)=>window.confirmRevoke=fn;openOwnerSessionAction('revoke','old-session');state.authentication={session:{id:'new-session'}};state.csrfToken='new-csrf';ownerSessions.devices=[{id:'new-session',deviceLabel:'New current',current:true}];window.calls=[];fetch=async(path,options)=>{window.calls.push({path,options});return {status:200,ok:true,json:async()=>path==='/api/auth'?{enabled:false}:{current:false}}};location.replace=path=>window.redirect=path`);await h.run('window.confirmRevoke()');const call=h.run(`window.calls.find(c=>c.options.method==='POST')`);assert.equal(call.path,'/api/auth/devices/old-session/revoke');assert.equal(call.options.headers['x-opendots-csrf'],'new-csrf');assert.equal(h.run('authEnded'),false);assert.equal(h.run('window.redirect'),undefined);});
for(const stage of ['read','hash'])test(`logout during attachment ${stage} cannot retain late private File or recreate draft`,async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`location.replace=()=>{};attachmentLimits={mediaTypes:['text/plain'],maximumBytes:10485760,maximumFiles:4,maximumDraftBytes:20971520};window.complete=null;window.privateFile={name:'private.txt',type:'text/plain',size:1,arrayBuffer:()=>${stage==='read'?'new Promise(resolve=>window.complete=resolve)':'Promise.resolve(new Uint8Array([1]).buffer)'}};${stage==='hash'?'crypto={...crypto,subtle:{digest:()=>new Promise(resolve=>window.complete=resolve)}};':''}window.selection=chooseAttachments([window.privateFile])`);await new Promise(r=>setImmediate(r));h.run('leaveOwnerSession();window.complete(new Uint8Array([1]).buffer)');await h.run('window.selection');assert.equal(h.run('attachmentItems.length'),0);assert.equal(h.run('attachmentDraft'),null);assert.equal(h.run('authEnded'),true);});
test('attachment hash result is discarded if active owner session changes without logout',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`state.authentication={session:{id:'old'}};attachmentLimits={mediaTypes:['text/plain'],maximumBytes:100,maximumFiles:4,maximumDraftBytes:400};window.complete=null;window.selection=chooseAttachments([{name:'private.txt',type:'text/plain',size:1,arrayBuffer:()=>new Promise(resolve=>window.complete=resolve)}]);state.authentication.session.id='new';window.complete(new Uint8Array([1]).buffer)`);await h.run('window.selection');assert.equal(h.run('attachmentItems.length'),0);assert.equal(h.run('attachmentDraft'),null);});

test('connector initial inventory is configuration only, never native refresh or external probe',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`view='settings';window.connectorCalls=[];request=async(path)=>{window.connectorCalls.push(path);return {status:'ready',callbackListening:true,nativeRegistration:'unverified',catalogue:{connectors:[{id:'github_public',label:'GitHub public repositories',status:{repositories:['owner/repo'],lastSuccessfulReadAt:null},operations:[{id:'get_repo',effect:'public_read',description:'Read repository'}]}]}}}`);await h.run('loadConnectors()');assert.deepEqual(Array.from(h.run('window.connectorCalls')),['/api/connectors']);const html=h.element('connector-inventory').innerHTML;assert.match(html,/回调监听已就绪/);assert.match(html,/账户连接：无/);assert.match(html,/owner\/repo/);assert.match(html,/get_repo/);assert.match(html,/不证明外部服务可用/);assert.doesNotMatch(html,/<form|type="password"|data-account/);});
test('explicit connector native refresh distinguishes declarations from connections and escapes fields',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`view='settings';window.connectorCalls=[];request=async(path)=>{window.connectorCalls.push(path);return path.endsWith('/native')?{source:'morphz_execution_targets',evidence:'declared_capabilities_only',targets:[{id:'<script>x</script>',status:'advertised',capabilities:['<img>']}]}:{status:'configured',nativeRegistration:'advertised',catalogue:{connectors:[]}}}`);await h.run('loadConnectors(true)');assert.deepEqual(Array.from(h.run('window.connectorCalls')),['/api/connectors/native','/api/connectors']);assert.match(h.element('connector-inventory').innerHTML,/非连接验证/);assert.match(h.element('connector-inventory').innerHTML,/&lt;script&gt;/);assert.doesNotMatch(h.element('connector-inventory').innerHTML,/<script>|<img>/);});
test('disabled and failed connector inventories do not retain stale registered operations',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`view='settings';connectorInventory={status:'ready',catalogue:{connectors:[{label:'stale-private-label'}]}};request=async()=>({status:'disabled',connectors:[]})`);await h.run('loadConnectors()');assert.match(h.element('connector-inventory').innerHTML,/此部署没有启用连接器/);assert.doesNotMatch(h.element('connector-inventory').innerHTML,/stale-private-label/);h.run(`request=async()=>{throw new Error('offline')}`);await h.run('loadConnectors()');assert.equal(h.run('connectorInventory'),null);assert.match(h.element('connector-inventory').innerHTML,/当前状态未确认/);});
test('late connector response cannot recreate state after logout or session replacement',async()=>{for(const mode of ['logout','replace']){const h=harness();await new Promise(r=>setImmediate(r));h.run(`view='settings';state.authentication={session:{id:'first'}};request=()=>new Promise(resolve=>window.resolveConnector=resolve);window.loadingConnector=loadConnectors();location.replace=()=>{};${mode==='logout'?'leaveOwnerSession()':"state.authentication.session.id='second'"};window.resolveConnector({status:'ready',catalogue:{connectors:[{label:'private response'}]}})`);await h.run('window.loadingConnector');assert.equal(h.run('connectorInventory'),null);assert.doesNotMatch(h.element('content').innerHTML,/private response/);}});

test('forced Settings state refresh restores cached connector and owner session panels without probing',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`view='settings';ownerSessions={enabled:true,devices:[{id:'saved-device',deviceLabel:'My desktop',current:true}]};connectorInventory={status:'ready',nativeRegistration:'unverified',catalogue:{connectors:[{label:'Cached connector',status:{repositories:['owner/repo']},operations:[]}]}};window.refreshCalls=[];request=async(path)=>{window.refreshCalls.push(path);return {mode:'runtime',runtime:{status:'ready'},messages:[],jobs:[],approvals:[]}};document.getElementById('owner-sessions').innerHTML='正在读取登录状态…';document.getElementById('connector-inventory').innerHTML='正在读取配置清单…'`);await h.run('loadState(true)');assert.match(h.element('owner-sessions').innerHTML,/My desktop/);assert.match(h.element('owner-sessions').innerHTML,/data-owner-device="saved-device"/);assert.match(h.element('connector-inventory').innerHTML,/Cached connector/);assert.match(h.element('connector-inventory').innerHTML,/data-connectors="native"/);assert.deepEqual(Array.from(h.run('window.refreshCalls')),['/api/state']);});

const calendarRuleFixture={intent:'private recurring task',timeZone:'America/New_York',frequency:'weekly',localTime:'01:30',startDate:'2026-11-01',weekdays:[7],dst:{gap:'skip',overlap:'later'},missed:'skip_unsubmitted',resume:'skip_overdue_paused'};
const calendarTimeFixture={localDate:'2026-11-01',localTime:'01:30',timeZone:'America/New_York',instant:'2026-11-01T06:30:00.000Z',offset:'-05:00',ambiguous:true,overlap:'later',calculationVersion:'v1'};
test('calendar inventory uses stored instants and never auto previews or reconciles',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`view='tasks';window.calls=[];request=async(path)=>{window.calls.push(path);return {series:[{id:'cal',revision:1,rule:${JSON.stringify(calendarRuleFixture)},desiredState:'active',occurrence:{time:${JSON.stringify(calendarTimeFixture)},state:'confirmed',schedule:{status:'queued'}}}]}}`);await h.run('loadCalendars()');assert.deepEqual(Array.from(h.run('window.calls')),['/api/calendar-reminders']);assert.match(h.element('calendar-list').innerHTML,/06:30:00/);assert.match(h.element('calendar-list').innerHTML,/较晚/);});
test('calendar preview requires explicit confirmation and freezes original rule with stable key on unknown',async()=>{const storage=new Map<string,string>();const h=harness(storage);await new Promise(r=>setImmediate(r));h.run(`state.binding={sessionId:'s'};parseCalendarRule=()=>(${JSON.stringify(calendarRuleFixture)});window.calls=[];request=async(path,method,body)=>{window.calls.push({path,body});if(path.endsWith('/preview'))return {rule:${JSON.stringify(calendarRuleFixture)},occurrences:[${JSON.stringify(calendarTimeFixture)}],previewFingerprint:'fingerprint',calculationVersion:'v1',skippedGaps:[]};throw new Error('uncertain')}`);await h.run('previewCalendar({})');assert.equal(h.run('window.calls.length'),1);assert.match(h.element('modal').innerHTML,/可能产生供应商费用/);await h.run('submitCalendar()');await h.run('submitCalendar()');const calls=h.run('window.calls');assert.equal(calls[1].body.idempotencyKey,calls[2].body.idempotencyKey);assert.deepEqual(JSON.parse(JSON.stringify(calls[2].body.rule)),calendarRuleFixture);assert.equal(calls[2].body.confirmed,true);assert.doesNotMatch([...storage.values()].join(''),/private recurring task|New_York/);});
test('calendar unknown create reload recovers exact authoritative key and rule without another preview',async()=>{const storage=new Map<string,string>();const h=harness(storage);await new Promise(r=>setImmediate(r));h.run(`state.binding={sessionId:'s'};saveCalendarAttempt({kind:'create',key:'original',previewFingerprint:'old'})`);const reloaded=harness(storage);await new Promise(r=>setImmediate(r));reloaded.run(`state.binding={sessionId:'s'};window.calls=[];request=async(path,method,body)=>{window.calls.push({path,body});return {series:[{id:'cal',createCommand:{idempotencyKey:'original'},rule:${JSON.stringify(calendarRuleFixture)},occurrence:{time:${JSON.stringify(calendarTimeFixture)}}}]}}`);await reloaded.run('recoverCalendar()');await reloaded.run('submitCalendar()');const submitted=reloaded.run(`window.calls.find(c=>c.body?.confirmed)`);assert.equal(submitted.body.idempotencyKey,'original');assert.equal(submitted.body.previewFingerprint,undefined);assert.deepEqual(JSON.parse(JSON.stringify(submitted.body.rule)),calendarRuleFixture);assert.equal(reloaded.run(`window.calls.some(c=>c.path.endsWith('/preview'))`),false);});
test('calendar controls keep displayed revision and retry identity after unknown reload',async()=>{const storage=new Map<string,string>();const h=harness(storage);await new Promise(r=>setImmediate(r));h.run(`state.binding={sessionId:'s'};calendarData.series=[{id:'cal',revision:4,rule:${JSON.stringify(calendarRuleFixture)},desiredState:'active'}];document.getElementById('calendar-control-confirm').addEventListener=(kind,fn)=>window.control=fn;controlCalendar('cal','pause');calendarData.series[0].revision=5;window.calls=[];request=async(path,method,body)=>{window.calls.push({path,body});throw new Error('unknown')}`);await h.run('window.control()');const original=h.run('window.calls[0].body');assert.equal(original.expectedRevision,4);const reloaded=harness(storage);await new Promise(r=>setImmediate(r));reloaded.run(`state.binding={sessionId:'s'};document.getElementById('calendar-control-confirm').addEventListener=(kind,fn)=>window.control=fn;window.calls=[];request=async(path,method,body)=>{window.calls.push({path,body});return {series:[{id:'cal',revision:9,rule:${JSON.stringify(calendarRuleFixture)}}]}}`);await reloaded.run('recoverCalendar()');await reloaded.run('window.control()');const retry=reloaded.run(`window.calls.find(c=>c.body?.confirmed).body`);assert.equal(retry.expectedRevision,4);assert.equal(retry.idempotencyKey,original.idempotencyKey);assert.equal(retry.action,'pause');});
test('calendar preview cannot replace a newer recording modal or submit after closing',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`parseCalendarRule=()=>({});request=()=>new Promise(resolve=>window.completePreview=resolve);window.preview=previewCalendar({});openModal('recording',{voice:true});voiceSession={status:'recording'};window.completePreview({rule:{},occurrences:[],previewFingerprint:'x'})`);await h.run('window.preview');assert.equal(h.element('modal').innerHTML,'recording');assert.equal(h.run('calendarPreview'),null);assert.equal(h.run('voiceSession.status'),'recording');});

test('stale calendar preview discards only preview and keeps same create identity for renewed consent',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`state.binding={sessionId:'s'};calendarPreview={rule:${JSON.stringify(calendarRuleFixture)},key:'original-key',previewFingerprint:'old',generation:modalGeneration,identity:connectorSessionIdentity()};request=async()=>{throw Object.assign(new Error('calendar_preview_changed'),{status:409,code:'calendar_preview_changed'})}`);await h.run('submitCalendar()');assert.equal(h.run('calendarPreview'),null);assert.equal(h.run('readCalendarAttempt().key'),'original-key');assert.equal(h.run('calendarRecoveryKey'),'original-key');h.run(`parseCalendarRule=()=>(${JSON.stringify(calendarRuleFixture)});request=async()=>({rule:${JSON.stringify(calendarRuleFixture)},occurrences:[${JSON.stringify(calendarTimeFixture)}],previewFingerprint:'fresh'})`);await h.run('previewCalendar({})');assert.equal(h.run('calendarPreview.key'),'original-key');assert.equal(h.run('calendarPreview.previewFingerprint'),'fresh');assert.equal(h.run('calendarPreview.sent'),false);});
test('calendar stale control revision is a definite rejection and never silently retargets',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`state.binding={sessionId:'s'};document.getElementById('calendar-control-confirm').addEventListener=(kind,fn)=>window.control=fn;openCalendarControl({id:'cal',revision:2,rule:{intent:'old'}},'pause');window.calls=[];request=async(path,method)=>{window.calls.push({path,method});if(method==='POST')throw Object.assign(new Error('calendar_revision_conflict'),{status:409,code:'calendar_revision_conflict'});return {series:[]}}`);await h.run('window.control()');assert.equal(h.run('readCalendarAttempt()'),null);assert.equal(h.run(`window.calls.filter(c=>c.method==='POST').length`),1);});
test('explicit reconcile is never called when user cancels confirmation',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run('window.confirm=()=>false');await h.run(`calendarAction('reconcile')`);assert.equal(h.requests.some(r=>r.path==='/api/calendar-reminders/reconcile'),false);});

test('calendar displayed consent cannot be reused under a different owner session',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`state.authentication={session:{id:'A'}};parseCalendarRule=()=>(${JSON.stringify(calendarRuleFixture)});window.calls=[];request=async(path,method,body)=>{window.calls.push(path);return {rule:${JSON.stringify(calendarRuleFixture)},occurrences:[${JSON.stringify(calendarTimeFixture)}],previewFingerprint:'p'}}`);await h.run('previewCalendar({})');h.run(`state.authentication.session.id='B'`);await h.run('submitCalendar()');assert.equal(h.run(`window.calls.filter(p=>p==='/api/calendar-reminders').length`),0);assert.equal(h.run('calendarPreview'),null);h.run(`document.getElementById('calendar-control-confirm').addEventListener=(kind,fn)=>window.control=fn;openCalendarControl({id:'cal',revision:1,rule:{intent:'private'}},'pause');state.authentication.session.id='C'`);await h.run('window.control()');assert.equal(h.run(`window.calls.some(p=>p.endsWith('/control'))`),false);});
test('late stale-preview response after logout cannot restore recovery state',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`location.replace=()=>{};calendarPreview={rule:${JSON.stringify(calendarRuleFixture)},key:'k',previewFingerprint:'p',generation:modalGeneration,identity:connectorSessionIdentity()};request=()=>new Promise((resolve,reject)=>window.rejectCalendar=reject);window.submission=submitCalendar();leaveOwnerSession();window.rejectCalendar(Object.assign(new Error('calendar_preview_changed'),{code:'calendar_preview_changed'}))`);await h.run('window.submission');assert.equal(h.run('calendarRecoveryKey'),null);assert.equal(h.run('calendarPreview'),null);});

test('confirmed external calendar control hold allows explicit fresh decision, unknown remains blocked',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`view='tasks';calendarData.series=[{id:'cal',revision:8,rule:${JSON.stringify(calendarRuleFixture)},desiredState:'paused',controlPending:true,recoveryDecisionRequired:true,occurrence:{state:'confirmed',time:${JSON.stringify(calendarTimeFixture)},schedule:{status:'queued',revision:5}}}];renderCalendars();document.getElementById('calendar-control-confirm').addEventListener=(kind,fn)=>window.control=fn;controlCalendar('cal','pause');window.calls=[];request=async(path,method,body)=>{window.calls.push({path,body});return {series:[]}}`);assert.match(h.element('calendar-list').innerHTML,/重新确认暂停/);assert.match(h.element('calendar-list').innerHTML,/重新确认恢复/);assert.match(h.element('modal').innerHTML,/排队中/);await h.run('window.control()');assert.equal(h.run(`window.calls.find(c=>c.body?.confirmed).body.expectedRevision`),8);h.run(`calendarData.series=[{id:'unknown',revision:9,rule:{intent:'unknown'},desiredState:'active',controlPending:true,recoveryDecisionRequired:false}];window.before=modalGeneration;controlCalendar('unknown','pause')`);assert.equal(h.run('modalGeneration===window.before'),true);assert.match(h.run('calendarControlButtons(calendarData.series[0])'),/disabled/);h.run(`calendarData.series[0]={...calendarData.series[0],desiredState:'cancelled',recoveryDecisionRequired:true,occurrence:{schedule:{status:'paused'}}}`);const buttons=h.run('calendarControlButtons(calendarData.series[0])');assert.match(buttons,/重新确认取消/);assert.doesNotMatch(buttons,/data-calendar-control="resume"|data-calendar-control="pause"/);});

const proposalFixture={proposalId:'p1',revision:3,state:'pending_owner_confirmation',rule:calendarRuleFixture,ruleFingerprint:'rule-fp',preview:{occurrences:[{instant:'HISTORICAL'}]},provenance:{jobId:'job',callId:'call',threadId:'thread'},createdAt:1,requiresOwnerConfirmation:true,scheduling:'not_admitted',seriesId:null};
const proposalPreviewFixture={proposalId:'p1',proposalRevision:3,ruleFingerprint:'rule-fp',rule:calendarRuleFixture,occurrences:[calendarTimeFixture],skippedGaps:[],calculationVersion:'v1',previewFingerprint:'fresh-fp'};
test('durable proposal inventory does not calculate preview or imply scheduling',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`view='tasks';window.calls=[];request=async(path)=>{window.calls.push(path);return {enabled:true,pendingCount:1,proposals:[${JSON.stringify(proposalFixture)}]}}`);await h.run('loadProposals()');assert.deepEqual(Array.from(h.run('window.calls')),['/api/calendar-proposals']);assert.match(h.element('proposal-list').innerHTML,/待你确认 · 尚未调度/);assert.doesNotMatch(h.element('proposal-list').innerHTML,/HISTORICAL/);h.run('state.calendarProposals={enabled:true,pendingCount:1}');assert.match(h.run('proposalNotice()'),/尚未排入日程/);});
test('owner opening proposal obtains fresh preview then explicit confirm freezes revision and fingerprints',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`window.calls=[];request=async(path,method,body)=>{window.calls.push({path,method,body});if(path.endsWith('/preview'))return ${JSON.stringify(proposalPreviewFixture)};if(path.endsWith('/confirm'))throw new Error('unknown');return {proposal:${JSON.stringify(proposalFixture)}}}`);await h.run(`openProposal('p1')`);assert.equal(h.run('window.calls.length'),2);assert.match(h.element('modal').innerHTML,/06:30:00/);assert.doesNotMatch(h.element('modal').innerHTML,/HISTORICAL/);h.run(`proposalData.proposals=[{...activeProposal.snapshot,revision:9,ruleFingerprint:'changed'}]`);await h.run(`proposalAction('confirm')`);await h.run(`proposalAction('confirm')`);const calls=h.run(`window.calls.filter(c=>c.path.endsWith('/confirm'))`);assert.equal(calls.length,2);for(const c of calls){assert.equal(c.body.expectedRevision,3);assert.equal(c.body.ruleFingerprint,'rule-fp');assert.equal(c.body.previewFingerprint,'fresh-fp');assert.equal(c.body.confirmed,true);assert.equal(c.body.idempotencyKey,undefined);}});
test('lost proposal confirmation reconciles admitted status without resubmitting or previewing',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`request=async(path)=>path.endsWith('/preview')?${JSON.stringify(proposalPreviewFixture)}:{proposal:${JSON.stringify(proposalFixture)}}`);await h.run(`openProposal('p1')`);h.run(`activeProposal.sent=true;window.calls=[];request=async(path)=>{window.calls.push(path);return {proposal:{...${JSON.stringify(proposalFixture)},state:'admitted',revision:4,seriesId:'cal'},series:{id:'cal',occurrence:{time:${JSON.stringify(calendarTimeFixture)}}}}}`);await h.run(`proposalAction('status')`);assert.deepEqual(Array.from(h.run('window.calls')),['/api/calendar-proposals/p1']);assert.match(h.element('modal').innerHTML,/计划已登记/);assert.match(h.element('modal').innerHTML,/保存的候选触发时刻/);assert.doesNotMatch(h.element('modal').innerHTML,/data-proposal-action="confirm"/);});
test('proposal stale preview blocks retries and dismiss-after-admitted directs series cancellation',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`request=async(path)=>path.endsWith('/preview')?${JSON.stringify(proposalPreviewFixture)}:{proposal:${JSON.stringify(proposalFixture)}}`);await h.run(`openProposal('p1')`);h.run(`window.calls=0;request=async()=>{window.calls++;throw Object.assign(new Error('calendar_preview_changed'),{code:'calendar_preview_changed'})}`);await h.run(`proposalAction('confirm')`);await h.run(`proposalAction('confirm')`);assert.equal(h.run('window.calls'),1);assert.match(h.element('modal').innerHTML,/重新打开/);h.run(`activeProposal.sent=false;request=async()=>{throw Object.assign(new Error('calendar_proposal_already_admitted'),{code:'calendar_proposal_already_admitted'})}`);await h.run(`proposalAction('dismiss')`);assert.match(h.element('modal').innerHTML,/日历计划中明确取消/);});
test('proposal session change, close and late preview cannot authorize or hide newer recording',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`state.authentication={session:{id:'A'}};request=async(path)=>path.endsWith('/preview')?${JSON.stringify(proposalPreviewFixture)}:{proposal:${JSON.stringify(proposalFixture)}}`);await h.run(`openProposal('p1')`);h.run(`state.authentication.session.id='B';window.writes=0;request=async()=>{window.writes++;return {}}`);await h.run(`proposalAction('confirm')`);assert.equal(h.run('window.writes'),0);h.run(`closeModal();request=async(path)=>path.endsWith('/preview')?new Promise(resolve=>window.finishPreview=resolve):{proposal:${JSON.stringify(proposalFixture)}};window.opening=openProposal('p1')`);await new Promise(r=>setImmediate(r));h.run(`openModal('recording',{voice:true});voiceSession={status:'recording'};window.finishPreview(${JSON.stringify(proposalPreviewFixture)})`);await h.run('window.opening');assert.equal(h.element('modal').innerHTML,'recording');assert.equal(h.run('activeProposal'),null);assert.equal(h.run('voiceSession.status'),'recording');});
test('repeated proposal confirm while in flight is single and stores no private intent',async()=>{const storage=new Map<string,string>();const h=harness(storage);await new Promise(r=>setImmediate(r));h.run(`request=async(path)=>path.endsWith('/preview')?${JSON.stringify(proposalPreviewFixture)}:{proposal:${JSON.stringify(proposalFixture)}}`);await h.run(`openProposal('p1')`);h.run(`window.writes=0;request=()=>{window.writes++;return new Promise((resolve,reject)=>window.failConfirm=reject)};window.confirming=proposalAction('confirm')`);await h.run(`proposalAction('confirm')`);assert.equal(h.run('window.writes'),1);h.run(`window.failConfirm(new Error('unknown'))`);await h.run('window.confirming');assert.doesNotMatch([...storage.values()].join(''),/private recurring task|rule-fp/);});

test('proposal occurrence labels distinguish pending unknown skipped and confirmed native receipt',()=>{const h=harness();for(const status of ['pending','unknown','skipped']){const html=h.run(`proposalOccurrenceHtml({state:'${status}',time:${JSON.stringify(calendarTimeFixture)}})`);assert.match(html,/保存的候选触发时刻/);assert.match(html,/尚无原生调度回执/);assert.doesNotMatch(html,/实际已登记|下一次时刻|已收到原生回执/);}const confirmed=h.run(`proposalOccurrenceHtml({state:'confirmed',time:${JSON.stringify(calendarTimeFixture)},schedule:{status:'paused',revision:5}})`);assert.match(confirmed,/原生回执状态：已暂停/);assert.match(confirmed,/版本 5/);const unknown=h.run(`proposalOccurrenceHtml({state:'unknown',time:${JSON.stringify(calendarTimeFixture)},schedule:{status:'queued',revision:4}})`);assert.match(unknown,/保留的原生回执（当前结果尚未确认）/);});
test('navigating away with modal hidden invalidates pending proposal detail and preview',async()=>{for(const barrier of ['detail','preview']){const h=harness();await new Promise(r=>setImmediate(r));h.run(`document.getElementById('modalback').hidden=true;request=async(path)=>{if(path==='/api/calendar-proposals/p1'&&'${barrier}'==='detail')return new Promise(resolve=>window.finishOpen=resolve);if(path.endsWith('/preview'))return new Promise(resolve=>window.finishOpen=resolve);if(path==='/api/artifacts')return {artifacts:[]};return {proposal:${JSON.stringify(proposalFixture)}}};window.opening=openProposal('p1')`);await new Promise(r=>setImmediate(r));h.run(`navigate('files');window.finishOpen(${barrier==='detail'?`{proposal:${JSON.stringify(proposalFixture)}}`:JSON.stringify(proposalPreviewFixture)})`);await h.run('window.opening');assert.equal(h.run('view'),'files');assert.equal(h.element('modalback').hidden,true);assert.equal(h.run('activeProposal'),null);}});
test('disabled new proposal creation retains durable owner review and outcome actions',()=>{const h=harness();h.run(`view='tasks';proposalData={enabled:false,proposals:[${JSON.stringify(proposalFixture)},{...${JSON.stringify(proposalFixture)},proposalId:'admitted',state:'admitted'}],nextCursor:'next'};renderProposals()`);const html=h.element('proposal-list').innerHTML;assert.match(html,/新对话提案创建已停用/);assert.match(html,/data-proposal-id="p1"/);assert.match(html,/data-proposal-id="admitted"/);assert.match(html,/查看新预览并决定/);assert.match(html,/核对提案结果/);assert.match(html,/加载更多提案/);assert.doesNotMatch(html,/此功能需要所有者登录/);});

const docFixture={id:'doc-11111111-1111-4111-8111-111111111111',title:'Private document',revision:4,currentVersionId:'ver-22222222-2222-4222-8222-222222222222',createdAt:1,updatedAt:1};
const resourceFixture={id:'artifact-id',name:'private.txt',sha256:'sha',sourceEventId:'event',mediaType:'text/plain',sizeBytes:42,origin:'output'};
function setArtifactForm(h:ReturnType<typeof harness>,values:Record<string,string>){h.run(`FormData=class {get(key){return ${JSON.stringify(values)}[key]??null}}`);}
test('version append freezes displayed document head and resource through unknown retries',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`activeDocument={document:${JSON.stringify(docFixture)}};request=async()=>({artifacts:[${JSON.stringify(resourceFixture)}]})`);await h.run(`openArtifactEditor('append')`);setArtifactForm(h,{artifactId:'artifact-id',note:'Private note'});h.run(`previewArtifactVersion({});activeDocument={document:{...${JSON.stringify(docFixture)},revision:9,currentVersionId:'new'}};window.calls=[];request=async(path,method,body)=>{window.calls.push({path,body});throw new Error('unknown')}`);await h.run('submitArtifactVersion()');await h.run('submitArtifactVersion()');const calls=h.run('window.calls');assert.equal(calls[0].body.expectedRevision,4);assert.equal(calls[1].body.parentVersionId,docFixture.currentVersionId);assert.equal(calls[1].body.artifactId,'artifact-id');assert.equal(calls[1].body.idempotencyKey,calls[0].body.idempotencyKey);assert.equal(calls[1].body.note,'Private note');});
test('version retry storage contains only nonsecret identity and reload absent receipt keeps same target',async()=>{const storage=new Map<string,string>();const h=harness(storage);await new Promise(r=>setImmediate(r));h.run(`state.binding={sessionId:'s'};saveArtifactAttempt({kind:'append',key:'original-key',documentId:'${docFixture.id}',artifactId:'artifact-id',expectedRevision:4,parentVersionId:'${docFixture.currentVersionId}'})`);assert.doesNotMatch([...storage.values()].join(''),/Private|note|title|sha/);const r=harness(storage);await new Promise(r=>setImmediate(r));r.run(`state.binding={sessionId:'s'};window.calls=[];request=async(path,method,body)=>{window.calls.push({path,method,body});if(path.startsWith('/api/artifact-commands/'))return {receipt:null};return {artifacts:[${JSON.stringify(resourceFixture)}]}}`);await r.run('recoverArtifactVersion()');assert.equal(r.run('artifactEditor.meta.key'),'original-key');assert.equal(r.run('artifactEditor.meta.expectedRevision'),4);assert.equal(r.run('artifactEditor.meta.artifactId'),'artifact-id');assert.equal(r.run(`window.calls.some(c=>c.method==='POST')`),false);assert.match(r.element('modal').innerHTML,/没有回执不代表请求失败/);});
test('version downloads only accept exact immutable same-document paths',()=>{const h=harness();const version={id:docFixture.currentVersionId,documentId:docFixture.id,downloadPath:`/api/artifact-documents/${docFixture.id}/versions/${docFixture.currentVersionId}/content`};assert.equal(h.run(`versionDownloadPath('${docFixture.id}',${JSON.stringify(version)})`),version.downloadPath);for(const path of ['https://evil.example/content','/api/artifacts/other/content',version.downloadPath+'?token=x'])assert.equal(h.run(`versionDownloadPath('${docFixture.id}',${JSON.stringify({...version,downloadPath:path})})`),null);assert.equal(h.run(`versionDownloadPath('${docFixture.id}',${JSON.stringify({...version,documentId:'different'})})`),null);});
test('late version editor open cannot revive abandoned navigation or authorization',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`request=()=>new Promise(resolve=>window.resolveCatalog=resolve);window.opening=openArtifactEditor('create','artifact-id');navigate('memory');window.resolveCatalog({artifacts:[${JSON.stringify(resourceFixture)}]})`);await h.run('window.opening');assert.equal(h.run('artifactEditor'),null);assert.equal(h.element('modalback').hidden,true);});
test('version history remains readable without native catalogue access and cannot edit arbitrary bytes',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`window.calls=[];request=async(path)=>{window.calls.push(path);return {document:${JSON.stringify(docFixture)},versions:[],nextCursor:null}}`);await h.run(`openArtifactDocument('${docFixture.id}')`);assert.deepEqual(Array.from(h.run('window.calls')),[`/api/artifact-documents/${docFixture.id}`]);assert.match(h.element('modal').innerHTML,/离线时可查看本地历史/);assert.doesNotMatch(h.element('modal').innerHTML,/type="file"|contenteditable|分享链接/);});

test('committed version receipt recovery never resubmits and labels admission history honestly',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`saveArtifactAttempt({kind:'create',key:'committed',artifactId:'artifact-id'});window.calls=[];request=async(path,method)=>{window.calls.push({path,method});return path.startsWith('/api/artifact-commands/')?{receipt:{command:{key:'committed',kind:'create',input:{title:'Private document',artifactId:'artifact-id'}},documentAtAdmission:${JSON.stringify(docFixture)},version:{id:'${docFixture.currentVersionId}',revision:4,artifact:${JSON.stringify(resourceFixture)}}}}:{documents:[]}}`);await h.run('recoverArtifactVersion()');assert.equal(h.run('readArtifactAttempt()'),null);assert.equal(h.run(`window.calls.some(c=>c.method==='POST')`),false);assert.match(h.element('modal').innerHTML,/不代表文档现在仍停留在这个版本/);});
test('artifact confirmation cannot transfer across owner sessions or repeat while in flight',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`state.authentication={session:{id:'A'}};request=async()=>({artifacts:[${JSON.stringify(resourceFixture)}]})`);await h.run(`openArtifactEditor('create','artifact-id')`);setArtifactForm(h,{title:'Doc',note:''});h.run(`previewArtifactVersion({});window.writes=0;request=()=>{window.writes++;return new Promise((resolve,reject)=>window.failVersion=reject)};window.submitting=submitArtifactVersion()`);await h.run('submitArtifactVersion()');assert.equal(h.run('window.writes'),1);h.run(`window.failVersion(new Error('unknown'))`);await h.run('window.submitting');h.run(`state.authentication.session.id='B'`);await h.run('submitArtifactVersion()');assert.equal(h.run('window.writes'),1);});
test('definite head conflict requires new explicit review and retains original key',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`activeDocument={document:${JSON.stringify(docFixture)}};request=async()=>({artifacts:[${JSON.stringify(resourceFixture)}]})`);await h.run(`openArtifactEditor('append')`);setArtifactForm(h,{artifactId:'artifact-id',note:'note'});h.run(`previewArtifactVersion({});window.originalKey=artifactEditor.meta.key;request=async()=>{throw Object.assign(new Error('artifact_version_head_conflict'),{code:'artifact_version_head_conflict'})}`);await h.run('submitArtifactVersion()');h.run(`request=async(path)=>path.startsWith('/api/artifact-commands/')?{receipt:null}:path==='/api/artifacts'?{artifacts:[${JSON.stringify(resourceFixture)}]}:{document:{...${JSON.stringify(docFixture)},revision:5,currentVersionId:'new-parent'}}`);await h.run('refreshArtifactHead()');assert.equal(h.run('artifactEditor.meta.key===window.originalKey'),true);assert.equal(h.run('artifactEditor.meta.expectedRevision'),5);assert.equal(h.run('artifactEditor.meta.parentVersionId'),'new-parent');assert.equal(h.run('artifactEditor.body'),null);assert.match(h.element('modal').innerHTML,/Private document/);});

const streamCapabilityFixture={available:true,provider:{label:'豆包',destination:'openspeech.bytedance.com'},operations:{transcribe:true,streamingDictation:true},capture:{maximumSeconds:30},stream:{available:true,streamingDictation:true,duplex:false,maximumSeconds:60}};
function prepareStreamFixture(h:ReturnType<typeof harness>){h.run(`voiceSession={kind:'stream',status:'idle',cap:${JSON.stringify(streamCapabilityFixture)},identity:connectorSessionIdentity(),text:''};window.streamCalls=[];window.captureEvents=[];streamCaptureFactory=async()=>options=>{window.streamCaptureOptions=options;return {async start(){window.captureEvents.push('start')},async stop(){window.captureEvents.push('stop')},async cancel(){window.captureEvents.push('cancel')}}};streamVoiceRequest=async(v,body)=>{window.streamCalls.push(body);if(body.action==='read')return new Promise(()=>{});return {id:v.streamId,revision:body.action==='open'?1:body.action==='push'?body.sequence+1:10,status:body.action==='finish'?'complete':'listening',text:body.action==='finish'?'最终文字':'临时文字',receivedSequence:body.sequence||0,expiresAt:Date.now()+60000,duplex:false,reviewRequired:true,sentToChat:false}}`);}
test('streaming choice requires configured capability and selection itself never opens microphone or provider',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`voiceSession={kind:'record',status:'idle',text:'',cap:${JSON.stringify(streamCapabilityFixture)}};renderVoice(true)`);assert.match(h.element('modal').innerHTML,/stream-choice/);const count=h.requests.length;h.run('selectStreamingVoice()');assert.equal(h.requests.length,count);assert.match(h.element('modal').innerHTML,/持续发送给/);assert.match(h.element('modal').innerHTML,/openspeech.bytedance.com/);assert.match(h.element('modal').innerHTML,/可能按供应商规则收费/);assert.match(h.element('modal').innerHTML,/不会自动发送消息、朗读或重连/);h.run(`voiceSession={kind:'record',status:'idle',text:'',cap:{...${JSON.stringify(streamCapabilityFixture)},stream:{available:false,streamingDictation:false}}};renderVoice()`);assert.doesNotMatch(h.element('modal').innerHTML,/stream-choice/);});
test('streaming pushes ordered bounded frames and stop finishes to editable unsent final text',async()=>{const h=harness();await new Promise(r=>setImmediate(r));prepareStreamFixture(h);await h.run('startStreamVoice()');await h.run(`window.streamCaptureOptions.onFrame(new Uint8Array([1,2]),null)`);await h.run(`window.streamCaptureOptions.onFrame(new Uint8Array([3,4]),null)`);await h.run('finishStreamVoice()');const calls=h.run('window.streamCalls');assert.equal(calls[0].action,'open');assert.equal(calls[0].consent,true);assert.deepEqual(Array.from(calls.filter((c:any)=>c.action==='push').map((c:any)=>c.sequence)),[1,2]);assert.equal(h.run('voiceSession.status'),'review');assert.equal(h.run('voiceSession.text'),'最终文字');assert.match(h.element('modal').innerHTML,/已收到最终转写/);assert.match(h.element('modal').innerHTML,/id="voice-transcript"/);assert.equal(calls.some((c:any)=>c.action==='chat'),false);assert.equal(h.run('window.captureEvents.includes("stop")'),true);});
test('stream failure cancels provider, stops tracks and discards partial transcript without reconnect',async()=>{const h=harness();await new Promise(r=>setImmediate(r));prepareStreamFixture(h);await h.run('startStreamVoice()');h.run(`voiceSession.text='private partial'`);await h.run(`failStreamVoice(voiceSession,new Error('network unavailable'))`);assert.equal(h.run('voiceSession.text'),'');assert.equal(h.run('voiceSession.status'),'stream-error');assert.equal(h.run('voiceSession.streamCancelSent'),true);assert.equal(h.run('window.captureEvents.includes("cancel")'),true);assert.equal(h.requests.filter(r=>r.path==='/api/voice/stream'&&JSON.parse(r.options.body).action==='cancel').length,1);});
test('background and replacement modal cancel streaming and erase partial state',async()=>{for(const mode of ['background','modal']){const h=harness();await new Promise(r=>setImmediate(r));prepareStreamFixture(h);await h.run('startStreamVoice()');h.run(`window.oldStream=voiceSession;voiceSession.text='partial';document.getElementById('modalback').hidden=false;document.hidden=true`);if(mode==='background')for(const fn of h.events.get('visibilitychange')||[])fn();else h.run(`openModal('another dialog')`);await new Promise(r=>setImmediate(r));assert.equal(h.run('voiceSession'),null);assert.equal(h.run('window.oldStream.text'),'');assert.equal(h.run('window.oldStream.streamCancelSent'),true);assert.equal(h.run('window.captureEvents.includes("cancel")'),true);}});
test('owner-session replacement cancels active streaming before polling can repaint',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`state.authentication={session:{id:'A'}}`);prepareStreamFixture(h);await h.run('startStreamVoice()');h.run(`document.getElementById('modalback').hidden=false;request=async()=>({mode:'runtime',runtime:{status:'ready'},authentication:{session:{id:'B'}},messages:[],jobs:[],approvals:[]})`);await h.run('loadState()');assert.equal(h.run('voiceSession'),null);assert.equal(h.run('window.captureEvents.includes("cancel")'),true);});
test('late capture module cannot acquire microphone after stream consent is cancelled',async()=>{const h=harness();await new Promise(r=>setImmediate(r));prepareStreamFixture(h);h.run(`streamCaptureFactory=()=>new Promise(resolve=>window.resolveFactory=resolve);window.startingStream=startStreamVoice();closeModal();window.resolveFactory(()=>{throw new Error('must not create capture')})`);await h.run('window.startingStream');assert.equal(h.run('voiceSession'),null);assert.equal(h.run('window.streamCalls.length'),0);assert.equal(h.requests.filter(r=>r.path==='/api/voice/stream'&&JSON.parse(r.options.body).action==='cancel').length,1);});

test('graceful streaming stop never aborts in-flight transport before finish',async()=>{const h=harness();await new Promise(r=>setImmediate(r));prepareStreamFixture(h);await h.run('startStreamVoice()');h.run(`window.transportAborts=0;voiceSession.streamControllers=new Set([{abort(){window.transportAborts++}}]);streamVoiceRequest=async(v,body)=>({id:v.streamId,revision:5,status:'finishing',text:'pending',receivedSequence:0,expiresAt:Date.now()+60000,duplex:false,reviewRequired:true,sentToChat:false})`);await h.run('finishStreamVoice()');assert.equal(h.run('window.transportAborts'),0);assert.equal(h.run('voiceSession.streamCancelSent'),false);assert.equal(h.run('voiceSession.status'),'stream-finishing');assert.equal(h.run('window.captureEvents.includes("stop")'),true);});
test('oversized streaming frame is rejected before network push and final text cannot regress',async()=>{const h=harness();await new Promise(r=>setImmediate(r));prepareStreamFixture(h);await h.run('startStreamVoice()');await assert.rejects(h.run('window.streamCaptureOptions.onFrame(new Uint8Array(6402),null)'));assert.equal(h.run(`window.streamCalls.some(c=>c.action==='push')`),false);await h.run('finishStreamVoice()');h.run(`applyStreamVoice(voiceSession,{revision:99,status:'listening',text:'old partial'})`);assert.equal(h.run('voiceSession.text'),'最终文字');assert.equal(h.run('voiceSession.status'),'review');});

test('server finishing releases capture and suppresses queued pushes without aborting read transport',async()=>{const h=harness();await new Promise(r=>setImmediate(r));prepareStreamFixture(h);await h.run('startStreamVoice()');h.run(`window.transportAborts=0;voiceSession.streamControllers=new Set([{abort(){window.transportAborts++}}]);applyStreamVoice(voiceSession,{revision:7,status:'finishing',text:'still partial',expiresAt:Date.now()+3000})`);await new Promise(r=>setImmediate(r));await h.run('window.streamCaptureOptions.onFrame(new Uint8Array([1,2]),null)');assert.equal(h.run('window.captureEvents.includes("stop")'),true);assert.equal(h.run('window.streamCalls.some(c=>c.action==="push")'),false);assert.equal(h.run('window.transportAborts'),0);assert.equal(h.run('voiceSession.status'),'stream-finishing');h.run(`applyStreamVoice(voiceSession,{revision:8,status:'complete',text:'valid final'})`);assert.equal(h.run('voiceSession.status'),'review');assert.equal(h.run('voiceSession.text'),'valid final');});
test('oversized reviewed transcript stays editable and does not freeze a chat attempt',async()=>{const h=harness();await new Promise(r=>setImmediate(r));h.run(`voiceSession={kind:'stream',status:'review',cap:${JSON.stringify(streamCapabilityFixture)},text:'',error:''};document.getElementById('voice-transcript').value='x'.repeat(4001)`);await h.run('sendVoiceTranscript()');assert.equal(h.run('voiceSession.attempt'),undefined);assert.equal(h.run('voiceSession.text.length'),4001);assert.match(h.element('modal').innerHTML,/请在发送前缩短内容/);assert.doesNotMatch(h.element('modal').innerHTML,/readonly/);assert.equal(h.requests.some(r=>r.path==='/api/chat'),false);});

test('remote finishing during microphone setup treats expected setup abort as graceful stop',async()=>{const h=harness();await new Promise(r=>setImmediate(r));prepareStreamFixture(h);h.run(`streamCaptureFactory=async()=>options=>{window.streamCaptureOptions=options;return {start:()=>new Promise((resolve,reject)=>window.abortStart=reject),async stop(){window.captureEvents.push('stop')},async cancel(){window.captureEvents.push('cancel')}}};window.starting=startStreamVoice()`);await new Promise(r=>setImmediate(r));h.run(`applyStreamVoice(voiceSession,{revision:8,status:'finishing',text:'pending final'});window.abortStart(Object.assign(new Error('capture setup stopped'),{name:'AbortError'}))`);await h.run('window.starting');assert.equal(h.run('voiceSession.status'),'stream-finishing');assert.equal(h.run('voiceSession.streamCancelSent'),false);assert.equal(h.run('window.captureEvents.includes("stop")'),true);h.run(`applyStreamVoice(voiceSession,{revision:9,status:'complete',text:'kept final'})`);assert.equal(h.run('voiceSession.text'),'kept final');assert.equal(h.run('voiceSession.status'),'review');});

test('local graceful stop during setup preserves provider finishing while finish response is delayed',async()=>{const h=harness();await new Promise(r=>setImmediate(r));prepareStreamFixture(h);h.run(`streamCaptureFactory=async()=>options=>({start:()=>new Promise((resolve,reject)=>window.abortLocalStart=reject),async stop(){window.captureEvents.push('stop')},async cancel(){window.captureEvents.push('cancel')}});streamVoiceRequest=async(v,body)=>{window.streamCalls.push(body);if(body.action==='read')return new Promise(()=>{});if(body.action==='finish')return new Promise(resolve=>window.finishProvider=resolve);return {id:v.streamId,revision:1,status:'listening',text:'',receivedSequence:0,expiresAt:Date.now()+60000,duplex:false,reviewRequired:true,sentToChat:false}};window.startingLocal=startStreamVoice()`);await new Promise(r=>setImmediate(r));h.run('window.finishingLocal=finishStreamVoice()');await new Promise(r=>setImmediate(r));h.run(`window.abortLocalStart(Object.assign(new Error('setup stopped'),{name:'AbortError'}))`);await h.run('window.startingLocal');assert.equal(h.run('voiceSession.streamCancelSent'),false);assert.equal(h.run('voiceSession.status'),'stream-finishing');h.run(`window.finishProvider({id:voiceSession.streamId,revision:3,status:'complete',text:'preserved local final'})`);await h.run('window.finishingLocal');assert.equal(h.run('voiceSession.status'),'review');assert.equal(h.run('voiceSession.text'),'preserved local final');});
